dashboard.definition:
{
	"dataSources": {
		"ds_dns_sv_name_res_failed_table": {
			"name": "ds_dns_sv_name_res_failed_table",
			"options": {
				"extend": "ds_dns_tbl_name_res_failed_table",
				"query": "| `format_zero_count(count, Query)`"
			},
			"type": "ds.chain"
		},
		"ds_dns_sv_name_res_nxdomain_base": {
			"name": "ds_dns_sv_name_res_nxdomain_base",
			"options": {
				"extend": "ds_dns_tbl_name_res_nxdomain_base",
				"query": "|`format_zero_count(count, Source)`"
			},
			"type": "ds.chain"
		},
		"ds_dns_sv_name_res_query_response_base": {
			"name": "ds_dns_sv_name_res_query_response_base",
			"options": {
				"extend": "ds_dns_tbl_name_res_query_response_base",
				"query": "| `format_zero_count_rows(count, Query)`"
			},
			"type": "ds.chain"
		},
		"ds_dns_sv_name_rest_qtype_table": {
			"name": "ds_dns_sv_name_rest_qtype_table",
			"options": {
				"extend": "ds_dns_tbl_name_rest_qtype_table",
				"query": "| `format_zero_count(count, Qtype)`"
			},
			"type": "ds.chain"
		},
		"ds_dns_sv_responding_servers": {
			"name": "ds_dns_sv_responding_servers",
			"options": {
				"extend": "ds_dns_tbl_responding_servers",
				"query": "| stats count"
			},
			"type": "ds.chain"
		},
		"ds_dns_sv_volume_count": {
			"name": "ds_dns_sv_volume_count",
			"options": {
				"query": "`corelight_idx` sensor_name=$tkn_sensor_name|s$ `corelight_evt_conn` service=dns\n| append \n    [ makeresults \n    | eval orig_bytes = 0] \n| stats sum(orig_bytes) as TotalTraffic \n| eval formatted_traffic=case(\n    TotalTraffic >= (1024*1024*1024*1024), round(TotalTraffic / (1024*1024*1024*1024), 2) . \" TB\",\n    TotalTraffic >= (1024*1024*1024), round(TotalTraffic / (1024*1024*1024), 2) . \" GB\",\n    TotalTraffic >= (1024*1024), round(TotalTraffic / (1024*1024), 2) . \" MB\",\n    TotalTraffic >= 1024, round(TotalTraffic / 1024, 2) . \" KB\",\n    1=1, \"0 B\" \n    ) \n| table formatted_traffic",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_name_res_failed_table": {
			"name": "ds_dns_tbl_name_res_failed_table",
			"options": {
				"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns`\n(rcode_name=\"SERVFAIL\" OR rcode_name=\"REFUSED\" OR rcode_name=\"FORMERR\" OR rcode_name=\"NOTIMP\" OR rcode_name=\"NOTAUTH\")\n| table id.orig_h, id.resp_h, rcode_name, query | stats last(id.orig_h) as Source, last(id.resp_h) as Responder, last(query) as Query count by rcode_name\n| rename rcode_name as \"Response Code\"\n",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_name_res_nxdomain_base": {
			"name": "ds_dns_tbl_name_res_nxdomain_base",
			"options": {
				"enableSmartSources": true,
				"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` rcode_name=\"NXDOMAIN\"\n| eval query_rejected=if(rejected=true, \"Yes\", \"No\")\n| stats count by id.orig_h, id.resp_h, query, query_rejected \n| rename id.orig_h as Source, id.resp_h as Responder, query as Query, query_rejected as \"Rejected?\"\n| sort 0 - count",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_name_res_query_response_base": {
			"name": "ds_dns_tbl_name_res_query_response_base",
			"options": {
				"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns`\n| stats avg(rtt) as avg_rtt by query, id.resp_h\n| where avg_rtt > 0.015\n| eval avg_rtt = round(avg_rtt*1000, 2)  \n| rename query as Query, id.resp_h as Responder, avg_rtt as \"Avg. Response Time (ms)\"\n| table Query, Responder, \"Avg. Response Time (ms)\"",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_name_rest_qtype_table": {
			"name": "ds_dns_tbl_name_rest_qtype_table",
			"options": {
				"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` qtype_name IN (\"AXFR\", \"IXFR\", \"ANY\", \"TXT\") \n| stats last(id.orig_h) as Source, last(query) as Query,  count by qtype_name, id.resp_h\n| rename qtype_name as Qtype, id.resp_h as Responder\n| sort 0 -count",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_query_volume": {
			"name": "ds_dns_tbl_query_volume",
			"options": {
				"query": "`corelight_idx` sensor_name=$tkn_sensor_name|s$ `corelight_evt_dns` \n| timechart count \n",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_tbl_responding_servers": {
			"name": "ds_dns_tbl_responding_servers",
			"options": {
				"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` dest_ip=* \n| iplocation dest_ip \n| fillnull value=\"Unknown\" Country Region City \n| `classify_ip(dest_ip)` \n| stats count(query) as \"# of Queries\" dc(src_ip) as \"# of Unique Clients\" values(Country) as Country values(ip_class) as Internal by dest_ip \n| eval Internal = if(Internal = \"Internal\", \"yes\", \"no\") \n| rename dest_ip as Destination \n| sort 0 -\"# of Queries\" \"# of Unique Clients\"",
				"queryParameters": {
					"earliest": "$time_restriction.earliest$",
					"latest": "$time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_lookup_corelight_systems": {
			"name": "corelight_system_csv",
			"options": {
				"query": "|inputlookup corelight_systems"
			},
			"type": "ds.search"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$time_restriction.earliest$",
						"latest": "$time_restriction.latest$"
					}
				}
			}
		},
		"tokens": {
			"default": {
				"key_count": {
					"value": "0"
				},
				"key_cout": {
					"value": "0"
				}
			}
		}
	},
	"description": "Insights on Name Resolution (DNS)",
	"inputs": {
		"input_sensor_name": {
			"dataSources": {
				"primary": "ds_lookup_corelight_systems"
			},
			"options": {
				"defaultValue": "*",
				"items": [
					{
						"label": "All",
						"value": "*"
					}
				],
				"token": "tkn_sensor_name"
			},
			"title": "Sensor",
			"type": "input.dropdown"
		},
		"input_time_restriction": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_restriction"
			},
			"title": "Global Time Restriction",
			"type": "input.timerange"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_restriction",
			"input_sensor_name"
