	"title": "Name Resolution Insights",
	"visualizations": {
		"viz_4XVQpvcJ": {
			"options": {
				"fontSize": "large",
				"markdown": "****Unusual Qtypes****"
			},
			"type": "splunk.markdown"
		},
		"viz_6usWu77y": {
			"options": {
				"fillColor": "transparent",
				"strokeColor": "transparent"
			},
			"type": "splunk.rectangle"
		},
		"viz_7T0F0MRR": {
			"dataSources": {
				"primary": "ds_dns_sv_name_res_query_response_base"
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"earliest": "auto",
						"latest": "auto",
						"newTab": true,
						"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns`\n| stats avg(rtt) as avg_rtt by query, id.resp_h\n| where avg_rtt > 0.015\n| eval avg_rtt = round(avg_rtt*1000, 2)  \n| rename query as Query, id.resp_h as Responder, avg_rtt as \"Avg. Response Time (ms)\"\n| table Query, Responder, \"Avg. Response Time (ms)\"",
						"type": "custom"
					}
				}
			],
			"options": {
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_9Mcsb9wb": {
			"dataSources": {
				"primary": "ds_dns_sv_volume_count"
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"type": "auto",
						"newTab": true
					}
				}
			],
			"options": {
				"majorValue": "> sparklineValues | lastPoint()",
				"sparklineDisplay": "off",
				"sparklineValues": "> primary | seriesByName('formatted_traffic')",
				"trendDisplay": "off",
				"trendValue": "> sparklineValues | delta(-2)"
			},
			"type": "splunk.singlevalue"
		},
		"viz_AixmleHX": {
			"options": {
				"fontSize": "large",
				"markdown": "******DNS Query Volume Over Time******"
			},
			"type": "splunk.markdown"
		},
		"viz_DlBxA7my": {
			"options": {
				"backgroundColor": "#000000",
				"markdown": "Monitor total DNS-related network traffic in MB/GB. Sudden spikes or unusual patterns could signal configuration errors, compromised devices making excessive queries, or potential data exfiltration attempts."
			},
			"type": "splunk.markdown"
		},
		"viz_FO2jhmT6": {
			"options": {
				"backgroundColor": "#000000",
				"markdown": "Long DNS query response times may indicate network congestion, server performance issues, or potential security threats. Timely analysis is crucial for maintaining optimal network performance and security. Investigate extended response times by examining server configurations, network traffic, and potential external attacks.\n\n"
			},
			"type": "splunk.markdown"
		},
		"viz_HCGdeFO9": {
			"dataSources": {
				"primary": "ds_dns_tbl_name_res_nxdomain_base"
			},
			"eventHandlers": [
				{
					"options": {
						"earliest": "auto",
						"latest": "auto",
						"newTab": true,
						"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` rcode_name=\"NXDOMAIN\"\n| eval query_rejected=if(rejected=true, \"Rejected\", \"Not Rejected\")\n| stats count by id.orig_h, id.resp_h, query, query_rejected \n| rename id.orig_h as Source, id.resp_h as Responder, query as Query, query_rejected as Rejected\n| sort 0 - count",
						"type": "custom"
					},
					"type": "drilldown.linkToSearch"
				}
			],
			"options": {
				"columnFormat": {
					"Dest_Host": {
						"width": 103
					},
					"Query": {
						"width": 143
					},
					"Rejected": {
						"width": 105
					},
					"Resp_port": {
						"width": 78
					},
					"Responder": {
						"width": 85
					},
					"id.resp_h": {
						"width": 106
					},
					"key_length": {
						"width": 98
					},
					"proto": {
						"width": 70
					},
					"query": {
						"width": 199
					},
					"query_rejected": {
						"width": 155
					},
					"subject": {
						"width": 220
					},
					"traffic_type": {
						"width": 85
					}
				},
				"font": "monospace",
				"fontSize": "small",
				"headerVisibility": "fixed",
				"showInternalFields": false
			},
			"title": "Network Evidence for NXDOMAIN Responses",
			"type": "splunk.table"
		},
		"viz_KrKe9HhS": {
			"dataSources": {
				"primary": "ds_dns_tbl_responding_servers"
			},
			"description": "",
			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"earliest": "auto",
						"latest": "auto",
						"newTab": true,
						"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` dest_ip=* \n| iplocation dest_ip \n| fillnull value=\"Unknown\" Country Region City \n| `classify_ip(dest_ip)` \n| stats count(query) as \"# of Queries\" dc(src_ip) as \"# of Unique Clients\" values(Country) as Country values(ip_class) as Internal values(Region) as Region by dest_ip \n| eval Internal = if(Internal = \"Internal\", \"yes\", \"no\") \n| rename dest_ip as Destination \n| sort 0 -\"# of Queries\" \"# of Unique Clients\"",
						"type": "custom"
					}
				}
			],
			"options": {
				"columnFormat": {
					"# of Queries": {
						"width": 68
					},
					"Country": {
						"width": 60
					},
					"Dest_Host": {
						"width": 103
					},
					"Host": {
						"width": 102
					},
					"Internal": {
						"width": 52
					},
					"No Valid After": {
						"width": 161
					},
					"Query": {
						"width": 114
					},
					"Resp_port": {
						"width": 78
					},
					"Subject": {
						"width": 248
					},
					"id.resp_p": {
						"width": 54
					},
					"ip_address": {
						"width": 83
					},
					"key_length": {
						"width": 98
					},
					"proto": {
						"width": 70
					},
