		"viz_cAfcfs1O": {
			"dataSources": {
				"primary": "ds_dns_sv_responding_servers"
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"earliest": "auto",
						"latest": "auto",
						"newTab": true,
						"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` dest_ip=* \n| iplocation dest_ip \n| fillnull value=\"Unknown\" Country Region City \n| `classify_ip(dest_ip)` \n| stats count(query) as \"# of Queries\" dc(src_ip) as \"# of Unique Clients\" values(Country) as Country values(ip_class) as Internal values(Region) as Region by dest_ip \n| eval Internal = if(Internal = \"Internal\", \"yes\", \"no\") \n| rename dest_ip as Destination \n| sort 0 -\"# of Queries\" \"# of Unique Clients\"",
						"type": "custom"
					}
				}
			],
			"options": {
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
