						"query": "`corelight_idx`  sensor_name=$tkn_sensor_name|s$  `corelight_evt_dns` qtype_name IN (\"AXFR\", \"IXFR\", \"ANY\", \"TXT\") \n| stats last(id.orig_h) as Source, last(query) as Query,  count by qtype_name, id.resp_h\n| rename qtype_name as Qtype, id.resp_h as Responder\n| sort 0 -count",
